#!/usr/bin/env python3
from pathlib import Path
p=Path('/root/workspace/科武纪元/新版/第241章.md')
s=p.read_text(encoding='utf-8')
# Fix 1: RTL-SDR -> HackRF One (supports TX)
s=s.replace('RTL-SDR Blog V3','HackRF One')
s=s.replace('rtl2832 1-1.3:1.0: Registered as swradio0','hackrf 1-1.3:1.0: HackRF One detected, firmware OK')
# Fix 2: compress compilation - use pre-built image
s=s.replace('脚本开始跑。树莓派的风扇转速上去了，嗡嗡声比之前大了不少。CPU温度从四十二度升到六十七度。进度条走得慢。ARM架构编译C++代码本来就不快，树莓派的散热也一般。林泽远从抽屉里翻出一个小USB风扇，插在树莓派旁边，对着CPU那片吹。风速不大，但至少能让热气散得快一点。\n\n"多久？"林星辰问。\n\n"四十分钟到一小时。"林泽远说，"你先把手机装回去。"',
'"多久？"林星辰问。\n\n"不用编。"林泽远说，"三年前我就把交叉编译好的镜像放在安全屋里了。直接解压。"\n\n他从离线电脑的隔离包里拖出一个tar.gz，解压到树莓派的系统盘里。open5GS的核心网和srsRAN的基站软件都在里面。预编译的ARM二进制。不需要等编译。')
# Fix 3: add dark line + main line pressure
s=s.replace('林星辰把这四组数据写在纸上。他的笔尖在纸上停留了几秒。笔是黑色的中性笔，笔尖0.5毫米，墨水流得很匀。纸是安全屋里找到的旧笔记本，纸面发黄，边缘有卷曲。\n\n"如果第一组真的是坐标数据，那C2心跳不只是状态报告。它在向控制端发送观测结果。"\n\n"什么观测结果？"\n\n"赤经05h42m方向的扫频结果。"林星辰说，"我们昨晚扫了这个方向，底噪抬升。手机的心跳包把扫频结果编码后发给了控制端。说明控制端想知道我们看到了什么。"\n\n这意味着对方在监控他们的观测行动。而且他们不在乎被发现——至少不在乎被一个新闻聚合器的后门发现。\n\n而且对方在乎赤经05h42m这个方向。知道他们在看这个方向，并且想知道他们看到了什么。',
'林星辰把这四组数据写在纸上。他的笔尖在纸上停留了几秒。笔是黑色的中性笔，笔尖0.5毫米，墨水流得很匀。纸是安全屋里找到的旧笔记本，纸面发黄，边缘有卷曲。\n\n"如果第一组真的是坐标数据，那C2心跳不只是状态报告。它在向控制端发送观测结果。"\n\n"什么观测结果？"\n\n"赤经05h42m方向的扫频结果。"林星辰说，"我们昨晚扫了这个方向，底噪抬升。手机的心跳包把扫频结果编码后发给了控制端。说明控制端想知道我们看到了什么。"\n\n这意味着对方在监控他们的观测行动。而且他们不在乎被发现——至少不在乎被一个新闻聚合器的后门发现。\n\n而且对方在乎赤经05h42m这个方向。知道他们在看这个方向，并且想知道他们看到了什么。\n\n"这个蜜罐不只是抓数据。"林泽远说，"它还能反向发信号。如果对方用同样的协议来监听，我们可以伪造心跳包。给控制端发假的坐标数据。让它以为我们什么都没扫到。"\n\n"诱饵。"\n\n"对。让对方的注意力留在错误的方向上。给我们争取时间。"\n\n树莓派的散热风扇嗡嗡转着。窗外传来远处汽车的喇叭声，短促，尖锐。林星辰看了看手机屏幕上的时间：下午两点四十三分。\n\n距离东屿的经侦立案已经过去了一天。赵刚那边还没消息。如果铁幕先于经侦拿到东屿的产线数据，供应链的预警窗口就没了。')
p.write_text(s,encoding='utf-8')
chars=sum(1 for c in s if '\u4e00'<=c<='\u9fff')
print('chars',chars)
